/**
 * Self-destruct service worker.
 *
 * This file only exists to unregister the old SW registration at /sw.js.
 * The active SW is generated by Serwist at /service-worker.js.
 *
 * When a browser with the OLD /sw.js registration checks for updates
 * (which happens automatically on navigation), it fetches this file,
 * installs it, and this code runs — unregistering the old registration
 * and reloading every open tab.
 *
 * After this runs once, no SW is registered at /sw.js and this file
 * becomes inert.
 */
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Unregister this very registration
      await self.registration.unregister();

      // Reload every open client so they fetch fresh assets
      const clients = await self.clients.matchAll({ type: 'window' });
      for (const client of clients) {
        client.navigate(client.url);
      }
    })()
  );
});